import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"2025年 · 告别信","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2025年.md","filePath":"05_quotes/by-year/2025年.md"}'),r={name:"05_quotes/by-year/2025年.md"};function u(c,e,h,s,q,b){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2025年-·-告别信" tabindex="-1">2025年 · 告别信 <a class="header-anchor" href="#_2025年-·-告别信" aria-label="Permalink to &quot;2025年 · 告别信&quot;">​</a></h1><blockquote><p>精心选择你的榜样，然后效仿他们。你永远不会完美，但你总能变得更好。——巴菲特（95岁）</p></blockquote><p>本页收录2025年致股东信告别篇中的经典语录。这是巴菲特最后一封致股东信，他以95岁高龄正式宣布将接力棒交给格雷格·阿贝尔，回顾人生、感恩故人、寄语未来。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>我将不再撰写伯克希尔的年报，也不会在股东大会上滔滔不绝。用英国人的说法，我要&quot;归于平静&quot;了。</p></blockquote><blockquote><p>伟大，不是靠积累巨额财富、大量曝光或政府权力实现的。当你以成千上万种方式中的任何一种去帮助别人时，你就在帮助这个世界。</p></blockquote><blockquote><p>精心选择你的榜样，然后效仿他们。你永远不会完美，但你总能变得更好。</p></blockquote><blockquote><p>别指望报社搞错：先想好你希望讣告写些什么，然后活出配得上它的人生。</p></blockquote><blockquote><p>善意无需成本，却无价。无论你是否信教，黄金法则（己所不欲，勿施于人）都是最好的行为指南。</p></blockquote><blockquote><p>我人生的下半场比上半场更让我满意。我的建议是：不要为过去的错误自责——从中吸取一点教训，然后继续前行。什么时候变好都不晚。</p></blockquote><blockquote><p>记住：保洁阿姨和董事长一样，都是人。</p></blockquote><blockquote><p>我们的股价会随意波动，偶尔会下跌50%左右，过去60年现任管理层期间已经发生过三次。不要绝望；美国会复苏，伯克希尔的股票也会。</p></blockquote><hr><h2 id="关于格雷格·阿贝尔" tabindex="-1">关于格雷格·阿贝尔 <a class="header-anchor" href="#关于格雷格·阿贝尔" aria-label="Permalink to &quot;关于格雷格·阿贝尔&quot;">​</a></h2><blockquote><p>格雷格·阿贝尔完全达到了我最初选定他为下一任CEO时的高期望。他对我们很多业务和人员的了解，现在已经远胜于我。</p></blockquote><blockquote><p>运气好一点的话，下个世纪伯克希尔只需要五六位CEO就够了。尤其要避开那些目标是65岁退休、只想炫富、或想建立王朝的人。</p></blockquote><hr><h2 id="关于幸运与感恩" tabindex="-1">关于幸运与感恩 <a class="header-anchor" href="#关于幸运与感恩" aria-label="Permalink to &quot;关于幸运与感恩&quot;">​</a></h2><blockquote><p>幸运女神反复无常，用别的词形容就是——极度不公平。很多时候，我们的领袖和富人得到的好运远超他们应得的份额——而受益者往往不愿承认。</p></blockquote><blockquote><p>我1930年出生，健康、智商尚可、白人、男性、在美国。哇！谢谢你，幸运女神。</p></blockquote><blockquote><p>美国的中心地带，是出生、养家、创业的绝佳之地。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2025年11月10日，95岁的巴菲特发表最后一封致股东信，正式宣布将CEO职位交给格雷格·阿贝尔。这封信是巴菲特人生的回顾与告别，他追忆奥马哈的故人——查理·芒格、斯坦·利普西、沃尔特·斯科特、唐·基奥、阿吉特·贾因，感慨&quot;奥马哈的水里有什么魔力&quot;。他同时宣布加速生前捐赠计划，将更多股份转让给家族基金会。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2025年-翻译-·-01-letters-2025年-核心总结-·-01-letters-2025年-思维导图" tabindex="-1"><a href="/01_letters/2025年/翻译.html">01_letters/2025年/翻译</a> · <a href="/01_letters/2025年/核心总结.html">01_letters/2025年/核心总结</a> · <a href="/01_letters/2025年/思维导图.html">01_letters/2025年/思维导图</a> <a class="header-anchor" href="#_01-letters-2025年-翻译-·-01-letters-2025年-核心总结-·-01-letters-2025年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2025年/翻译]] · [[→ 核心总结|01_letters/2025年/核心总结]] · [[→ 思维导图|01_letters/2025年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2025年/翻译.html">/01_letters/2025年/翻译</a></li></ul>',30)])])}const _=t(r,[["render",u]]);export{p as __pageData,_ as default};
